export async function freshTokens() {
  const t = await getTokens();
  if (!t) return null;
  if (t.accessExpires - Date.now() > 2 * 3600 * 1000) return t;
  return tokenRequest({ grant_type: "refresh_token", refresh_token: t.refresh }, t);
}

