                  {p.action && <p className="action">{p.action}</p>}
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="card">
        <h2>Today’s production</h2>
        <p className="sub">Solar output in watts, every minute from the gateway</p>
        {points.length ? <DayLine points={points} startMs={dayStart} endMs={dayStart + 86400_000} /> : <p className="empty">No readings yet today.</p>}
      </section>

      {panels.length > 0 && (
        <section className="card">
          <h2>Panels</h2>
          <p className="sub">Each microinverter’s latest report · darker = closer to its own best</p>
          <PanelGrid panels={panels} />
        </section>
      )}

      <section className="card">
        <h2>Last 30 days</h2>
        <p className="sub">Energy produced per day, kWh{best ? ` · best day ${(best.wh / 1000).toFixed(1)} kWh on ${best.label}` : ""}</p>
        <Bars bars={days} unit="kWh" />
        <details>
          <summary>Show as table</summary>
          <table>
            <thead><tr><th>Day</th><th>kWh</th></tr></thead>
            <tbody>{[...days].reverse().map((d) => <tr key={d.key}><td>{d.label}</td><td>{d.value.toFixed(1)}</td></tr>)}</tbody>
          </table>
        </details>
      </section>

      <div className="two">
        <section className="card">
          <h2>Last 12 months</h2>
          <p className="sub">Energy produced per month, kWh</p>
          <Bars bars={months} unit="kWh" digits={0} height={180} />
        </section>
        <section className="card">
          <h2>Impact</h2>
          <div className="tiles stacked">
            <Tile label="CO₂ avoided (≈ US grid average)" value={lifetimeWh == null ? "—" : `${((lifetimeWh / 1000) * CO2_KG_PER_KWH / 1000).toFixed(1)} t`} />
            <Tile label="Average day, last 30" value={kwh((days.reduce((a, d) => a + d.value, 0) / days.length) * 1000)} />
            {summary?.size_w ? <Tile label="System size" value={`${(summary.size_w / 1000).toFixed(2)} kW`} /> : null}
          </div>
        </section>
      </div>

      <div className="two">
        <section className="card">
          <h2>Home use &amp; grid</h2>
          {live?.hasConsumption ? (
            <div className="tiles stacked">
              <Tile label="Home using" value={kw(live.homeW)} />
              <Tile label={live.gridW != null && live.gridW < 0 ? "Exporting to grid" : "Importing from grid"} value={kw(live.gridW == null ? null : Math.abs(live.gridW))} />
            </div>
          ) : (
            <p className="empty">Not available yet — your gateway’s consumption meter is disabled. Once a technician installs or enables the consumption CTs, this fills in automatically.</p>
          )}
        </section>
        <section className="card">
          <h2>Where the power goes</h2>
          {live?.ups ? (
            <div className="tiles stacked">
              <Tile label={`UPS load${live.ups.model ? ` · ${live.ups.model}` : ""}`} value={kw(live.ups.w)} />
              <Tile label="UPS battery" value={live.ups.batteryPct == null ? "—" : `${live.ups.batteryPct}%${live.ups.onBattery ? " · on battery" : ""}`} />
            </div>
          ) : (
            <p className="empty">Waiting for the APC UPS — connect it with APC’s USB data cable (940-0127) and the collector will report its load here.</p>
          )}
        </section>
      </div>

      {live?.batteries && (
        <section className="card">
          <h2>Battery</h2>
          <Tile label="Charge" value={`${live.batteries.socPct ?? "—"}%`} />
        </section>
      )}

      <footer className="foot muted">
        {cloudConfigured ? (
          tokens ? (
            <>Enphase cloud connected · {hits}/{MONTHLY_BUDGET} API calls this month{summary ? ` · synced ${ago(summary.fetchedAt)}` : ""} · <a href="/api/enphase/connect">reconnect</a></>
          ) : (
            <a className="button" href="/api/enphase/connect">Connect Enphase</a>
          )
        ) : (
          <>Enphase cloud keys not set</>
        )}
      </footer>
    </main>
  );
}

function Tile({ label, value }: { label: string; value: string }) {
  return (
    <div className="tile">
      <span className="label">{label}</span>
      <span className="value">{value}</span>
    </div>
  );
}

// Sequential blue ramp by output relative to the panel's own best report.
const RAMP = ["#cde2fb", "#9ec5f4", "#6da7ec", "#3987e5", "#256abf", "#184f95"];
function PanelGrid({ panels }: { panels: Panel[] }) {
  const sorted = [...panels].sort((a, b) => a.sn.localeCompare(b.sn));
  return (
    <ul className="panels">
      {sorted.map((p) => {
        const silent = isSilent(p);
        const ratio = p.max > 0 ? p.w / p.max : 0;
        const step = Math.min(RAMP.length - 1, Math.max(0, Math.floor(ratio * RAMP.length)));
        const title = silent
          ? `${p.sn} — not reporting${p.at ? ` since ${new Date(p.at * 1000).toLocaleDateString()}` : ""}`
          : `${p.sn} — ${p.w} W (best ${p.max} W), reported ${new Date(p.at * 1000).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}`;
        return (
          <li key={p.sn} className={silent ? "panel silent" : "panel"} title={title} style={silent ? undefined : { background: RAMP[step], color: step >= 3 ? "#fff" : "#0b0b0b" }}>
            {silent ? <span className="panel-x" aria-label="not reporting">✕</span> : <span className="panel-w">{p.w}</span>}
            <span className="panel-sn">…{p.sn.slice(-4)}</span>
          </li>
        );
      })}
    </ul>
  );
}

