          <span className="hero-value">{kw(solarNow)}</span>
        </div>
        <div className="tiles">
          <Tile label="Today" value={kwh(todayWh)} />
          <Tile label="This month" value={kwh(monthWh, 0)} />
          <Tile label="Lifetime" value={lifetimeWh == null ? "—" : `${(lifetimeWh / 1e6).toFixed(1)} MWh`} />
