import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "Create Next App",
  description: "Generated by create next app",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" className={`${geistSans.variable} ${geistMono.variable}`}>
      <body>{children}</body>
    </html>
  );
}

input.content:
:root {
  color-scheme: light;
  --page: #f9f9f7;
  --surface: #fcfcfb;
  --ink: #0b0b0b;
  --ink-2: #52514e;
  --muted: #898781;
  --grid: #e1e0d9;
  --axis: #c3c2b7;
  --border: rgba(11, 11, 11, 0.1);
  --series: #2a78d6;
  --series-strong: #184f95;
  --series-wash: rgba(42, 120, 214, 0.1);
  --good: #0ca30c;
  --warning: #fab219;
  --serious: #ec835a;
  --critical: #d03b3b;
  --info: #2a78d6;
  --radius: 14px;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --page: #0d0d0d;
    --surface: #1a1a19;
    --ink: #ffffff;
    --ink-2: #c3c2b7;
    --grid: #2c2c2a;
    --axis: #383835;
    --border: rgba(255, 255, 255, 0.1);
    --series: #3987e5;
    --series-strong: #86b6ef;
    --series-wash: rgba(57, 135, 229, 0.14);
    --info: #3987e5;
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --page: #0d0d0d;
  --surface: #1a1a19;
  --ink: #ffffff;
  --ink-2: #c3c2b7;
  --grid: #2c2c2a;
  --axis: #383835;
  --border: rgba(255, 255, 255, 0.1);
  --series: #3987e5;
  --series-strong: #86b6ef;
  --series-wash: rgba(57, 135, 229, 0.14);
  --info: #3987e5;
}

* { box-sizing: border-box; }
html, body { margin: 0; }
body {
  background: var(--page);
  color: var(--ink);
  font: 15px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--series); }
h1, h2 { margin: 0; font-weight: 600; }
h1 { font-size: 24px; }
h2 { font-size: 16px; display: flex; align-items: center; gap: 8px; }
p { margin: 0; }

.page { max-width: 1040px; margin: 0 auto; padding: 24px 16px 48px; display: grid; gap: 16px; }
.top { display: flex; justify-content: space-between; align-items: baseline; flex-wrap: wrap; gap: 8px; }
.muted, .sub, .label, .tick { color: var(--muted); }
.sub { font-size: 13px; margin: 2px 0 12px; }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px; min-width: 0; }
.two { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
@media (max-width: 720px) { .two { grid-template-columns: 1fr; } }
.notice { background: var(--series-wash); border-radius: 10px; padding: 10px 14px; }

.live-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 2px; vertical-align: 1px; }
.live-dot.on { background: var(--good); }
.live-dot.off { background: var(--muted); }

/* hero + tiles */
.hero { display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: space-between; }
.hero-main { display: grid; }
.hero-value { font-size: 52px; font-weight: 600; line-height: 1.05; letter-spacing: -0.02em; }
.label { font-size: 13px; }
.tiles { display: grid; grid-template-columns: repeat(4, minmax(110px, 1fr)); gap: 16px 24px; flex: 1; max-width: 640px; }
.tiles.stacked { grid-template-columns: 1fr 1fr; max-width: none; }
@media (max-width: 720px) { .tiles { grid-template-columns: 1fr 1fr; } }
.tile { display: grid; gap: 2px; }
.tile .value { font-size: 22px; font-weight: 600; }

/* problems */
.count { background: var(--critical); color: #fff; font-size: 12px; border-radius: 999px; padding: 1px 8px; }
.problems { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 12px; }
.problem { display: flex; gap: 12px; padding-top: 12px; border-top: 1px solid var(--grid); }
.problem:first-child { border-top: 0; padding-top: 0; }
.problem p { color: var(--ink-2); font-size: 14px; }
.problem .action { color: var(--ink); margin-top: 2px; }
.sev { font-size: 12px; color: var(--muted); text-transform: capitalize; margin-left: 4px; }
.status-icon { flex: none; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 700; color: #fff; }
.status-icon.critical { background: var(--critical); }
.status-icon.serious { background: var(--serious); }
.status-icon.warning { background: var(--warning); color: #0b0b0b; }
.status-icon.info { background: var(--info); font-style: italic; font-family: Georgia, serif; }
.status-icon.good { background: var(--good); display: inline-grid; vertical-align: middle; margin-right: 6px; }
.ok { margin-top: 8px; }
.empty { color: var(--ink-2); font-size: 14px; }

/* charts */
.chart { position: relative; width: 100%; }
.chart svg { display: block; overflow: visible; touch-action: pan-y; }
.chart .grid { stroke: var(--grid); stroke-width: 1; }
.chart .axis { stroke: var(--axis); stroke-width: 1; }
.chart .tick { font-size: 11px; fill: var(--muted); font-variant-numeric: tabular-nums; }
.chart .line { fill: none; stroke: var(--series); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
.chart .area { fill: var(--series-wash); }
.chart .dot { fill: var(--series); stroke: var(--surface); stroke-width: 2; }
.chart .crosshair { stroke: var(--axis); stroke-width: 1; }
.chart .bar { fill: var(--series); }
.chart .bar-hover { fill: var(--series-strong); }
.chart .bar-accent { fill: var(--series-strong); }
.tooltip {
  position: absolute; transform: translate(-50%, -100%); pointer-events: none; white-space: nowrap;
  background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 6px 10px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12); display: grid; font-size: 13px;
}
.tooltip span { color: var(--ink-2); }

details { margin-top: 10px; font-size: 13px; color: var(--ink-2); }
details summary { cursor: pointer; }
table { border-collapse: collapse; margin-top: 8px; font-variant-numeric: tabular-nums; }
td, th { text-align: left; padding: 3px 16px 3px 0; border-bottom: 1px solid var(--grid); }

/* panels heatmap */
.panels { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); gap: 2px; }
.panel { aspect-ratio: 1 / 1.25; border-radius: 6px; display: grid; place-content: center; text-align: center; gap: 2px; cursor: default; }
.panel-w { font-size: 16px; font-weight: 600; }
.panel-sn { font-size: 10px; opacity: 0.75; }
.panel.silent { background: transparent; border: 2px solid var(--critical); color: var(--ink-2); }
.panel-x { color: var(--critical); font-weight: 700; font-size: 16px; }

/* footer + login */
.foot { font-size: 13px; text-align: center; }
.button {
  display: inline-block; background: var(--series); color: #fff; border: 0; border-radius: 10px;
  padding: 10px 16px; font: inherit; font-weight: 600; text-decoration: none; cursor: pointer;
}
.login { min-height: 100vh; place-content: center; }
.login form { display: grid; gap: 14px; width: min(340px, 100%); }
.login label { display: grid; gap: 4px; }
.login input[type="password"] {
  font: inherit; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--axis);
  background: var(--page); color: var(--ink);
}
.error { color: var(--critical); font-size: 14px; }

