.panel-w { font-size: 16px; font-weight: 600; }
.panel-sn { font-size: 10px; opacity: 0.75; }
.panel.silent { background: transparent; border: 2px solid var(--critical); color: var(--ink-2); }
.panel-x { color: var(--critical); font-weight: 700; font-size: 16px; }

/* footer + login */
.foot { font-size: 13px; text-align: center; }
.button {
  display: inline-block; background: var(--series); color: #fff; border: 0; border-radius: 10px;
  padding: 10px 16px; font: inherit; font-weight: 600; text-decoration: none; cursor: pointer;
}
.login { min-height: 100vh; place-content: center; }
.login form { display: grid; gap: 14px; width: min(340px, 100%); }
.login label { display: grid; gap: 4px; }
.login input[type="password"] {
  font: inherit; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--axis);
  background: var(--page); color: var(--ink);
}
.error { color: var(--critical); font-size: 14px; }

