              ? `${p.sn} — not reporting${p.at ? ` since ${new Date(p.at * 1000).toLocaleDateString("en-US", { timeZone: TZ })}` : ""}`
              : `${p.sn} — ${p.w} W (best ${p.max} W), reported ${new Date(p.at * 1000).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", timeZone: TZ })}`;
            return (
              <div key={p.sn} role="listitem" className={silent ? "panel dead" : "panel"} title={title} style={{ ["--lvl" as string]: lvl.toFixed(2) }}>
                {silent ? (
                  <span className="panel-alert" aria-label="not reporting">!</span>
                ) : (
                  <span className="panel-w">{p.w}<small>W</small></span>
                )}
                <span className="panel-tag">IQ7+</span>
                <span className="panel-sn">{p.sn.slice(-4)}</span>
              </div>
            );
          }),
        )}
      </div>
    </div>
  );
}
'''
s=s.replace('import type { Panel } from "@/lib/types";','import type { Panel } from "@/lib/types";\nimport { placePanels } from "@/lib/layout";')
s=s.replace('<p className="sub">Each microinverter’s latest report · darker = closer to its own best</p>','<p className="sub">Roof layout · live watts per microinverter · brighter = closer to its own best</p>')
open(p,'w',encoding='utf8').write(s)
EOF
