.button:hover { filter: brightness(1.15); }
.login { min-height: 100vh; place-content: center; }
.login form { display: grid; gap: 16px; width: min(360px, 100%); }
.login label { display: grid; gap: 6px; }
.login input[type="password"] {
  font: 500 16px var(--font-num); padding: 10px 12px; color: var(--cyan);
