  color-scheme: dark;
  --bg: #07060f;
  --bg-2: #0d0b1d;
  --surface: rgba(18, 14, 38, 0.78);
  --surface-solid: #120e26;
  --ink: #eef3ff;
  --ink-2: #b9b4d9;
  --muted: #7a73a8;
  --cyan: #00f0ff;
  --cyan-dim: #0a7f93;
  --magenta: #ff2bd6;
  --purple: #8b3dff;
  --violet: #b98cff;
  --grid: rgba(139, 61, 255, 0.16);
  --axis: rgba(0, 240, 255, 0.35);
  --border: rgba(0, 240, 255, 0.18);
  --good: #2bff88;
  --warning: #ffd23f;
  --serious: #ff8a3d;
  --critical: #ff3366;
  --info: #00f0ff;
  --font-ui: var(--font-body), "Rajdhani", system-ui, sans-serif;
  --font-hud: var(--font-display), "Orbitron", system-ui, sans-serif;
  --font-num: var(--font-mono), "JetBrains Mono", ui-monospace, monospace;
  --cut: 14px;
