cd /c/Users/Anna/Desktop/Codestuff/solar-dashboard/collector && node --input-type=module -e '
import fs from "node:fs"; import https from "node:https";
const env=Object.fromEntries(fs.readFileSync(".env","utf8").split(/\r?\n/).filter(l=>l.includes("=")).map(l=>[l.slice(0,l.indexOf("=")),l.slice(l.indexOf("=")+1)]));
const agent=new https.Agent({rejectUnauthorized:false});
const get=p=>new Promise((res,rej)=>https.get({host:env.GATEWAY_HOST,path:p,agent,headers:{Authorization:"Bearer "+env.GATEWAY_TOKEN}},r=>{let b="";r.on("data",c=>b+=c);r.on("end",()=>res({code:r.statusCode,body:b}))}).on("error",rej));
const meters=JSON.parse((await get("/ivp/meters")).body);
const net=meters.find(m=>m.measurementType==="net-consumption");
console.log("net meter:",JSON.stringify(net));
for(let i=0;i<5;i++){
  const rd=JSON.parse((await get("/ivp/meters/readings")).body).find(r=>r.eid===net.eid);
  console.log(new Date().toLocaleTimeString(),"total A",rd.current,"VA",rd.apparentPower,"| legs:",rd.channels.map(c=>`${c.voltage.toFixed(0)}V ${c.current.toFixed(2)}A ${c.apparentPower.toFixed(0)}VA`).join(" ; "));
  await new Promise(r=>setTimeout(r,3000));
}
for (const p of ["/ivp/meters/cts","/ivp/meters/reports/consumption","/ivp/meters/ctrecords"]) { const r=await get(p); console.log(p, r.code, r.body.slice(0,300).replace(/\s+/g," ")); }
'

