    '// marker: a benchmark value drawn as a short line across that bar (e.g. expected production).\nexport type Bar = { key: string; label: string; value: number; tick?: string; highlight?: boolean; marker?: number };\nexport type Reference = { value: number; label: string };')
rep('export function Bars({ bars, unit, digits = 1, height = 200 }: { bars: Bar[]; unit: string; digits?: number; height?: number }) {',
    'export function Bars({ bars, unit, digits = 1, height = 200, reference, markerLabel }: { bars: Bar[]; unit: string; digits?: number; height?: number; reference?: Reference; markerLabel?: string }) {')
rep('const yMax = niceMax(Math.max(...bars.map((b) => b.value), 0));\n  const band','const yMax = niceMax(Math.max(...bars.map((b) => Math.max(b.value, b.marker ?? 0)), reference?.value ?? 0, 0));\n  const band')
rep('''              {b.tick && <text x={cx} y={height - 6} textAnchor="middle" className="tick">{b.tick}</text>}''','''              {b.marker != null && b.marker > 0 && <line x1={cx - bw / 2 - 3} x2={cx + bw / 2 + 3} y1={y(b.marker)} y2={y(b.marker)} className="marker" />}
              {b.tick && <text x={cx} y={height - 6} textAnchor="middle" className="tick">{b.tick}</text>}''')
rep('''      </svg>
      {hb && (
        <div className="tooltip" style={{ left: Math.min(Math.max(M.left + band * (hover! + 0.5), 70), width - 70), top: 0 }}>
          <strong>{fmtNum(hb.value, digits)} {unit}</strong>
          <span>{hb.label}</span>
        </div>
      )}''','''        {reference && (
          <g className="reference">
            <line x1={M.left} x2={width - M.right} y1={y(reference.value)} y2={y(reference.value)} />
            <text x={width - M.right} y={y(reference.value) - 6} textAnchor="end">{reference.label}</text>
          </g>
        )}
      </svg>
      {(markerLabel || reference) && (
        <div className="legend">
          <span><i className="key-bar" /> Actual</span>
          {markerLabel && <span><i className="key-marker" /> {markerLabel}</span>}
          {reference && <span><i className="key-ref" /> {reference.label}</span>}
        </div>
      )}
      {hb && (
        <div className="tooltip" style={{ left: Math.min(Math.max(M.left + band * (hover! + 0.5), 70), width - 70), top: 0 }}>
          <strong>{fmtNum(hb.value, digits)} {unit}</strong>
          {hb.marker != null && <span>{markerLabel ?? "Expected"}: {fmtNum(hb.marker, digits)} {unit} ({Math.round((hb.value / hb.marker) * 100)}%)</span>}
          <span>{hb.label}</span>
        </div>
      )}''')
open(p,'w',encoding='utf8').write(s)
